import app from 'flarum/admin/app';
import Stream from 'flarum/common/utils/Stream';
import AbstractBinPage from './AbstractBinPage';
export default class DiscussionsBinPage extends AbstractBinPage {
  itemsCount = (() => Stream(0))();
  getApiResourceType() {
    return 'discussions';
  }
  getTitleTranslationKey() {
    return 'walsgit-recycle-bin.admin.discussions_bin';
  }
  getModelName() {
    return 'discussion';
  }
  getSearchPlaceholderKey() {
    return 'walsgit-recycle-bin.admin.search_placeholder';
  }
  getSearchHelpTextKey() {
    return 'walsgit-recycle-bin.admin.search_help_text';
  }
  getTotalLabelKey() {
    return 'walsgit-recycle-bin.admin.total_hidden_discussions';
  }
  columns() {
    const items = super.columns();
    const baseUrl = app.forum.attribute('baseUrl');
    items.add('id', {
      name: app.translator.trans('walsgit-recycle-bin.admin.discussion_id'),
      content: discussion => discussion.id() ?? null
    }, 95);
    items.add('title', {
      name: app.translator.trans('walsgit-recycle-bin.admin.discussion_title'),
      content: discussion => m("a", {
        href: `${baseUrl}/d/${discussion.id()}`,
        target: "_blank"
      }, discussion.title())
    }, 90);
    return items;
  }
}
flarum.reg.add('walsgit-recycle-bin', 'admin/components/DiscussionsBinPage', DiscussionsBinPage);